using namespace roots::gui;
namespace {
int checks{};void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
Hash256 H(char c){return *Hash256::Parse(std::string(64,c));}
RequestContext Context(){return {*BackendSessionId::Make("backend"),{H('a')},*WalletId::Make("wallet"),*DocumentId::Make("document"),{7},{3}};}
rpc::Json Json(std::string s){auto j=rpc::Json::Parse(s);if(!j)throw std::runtime_error("fixture JSON");return *j;}
HistoryTransaction Tx(char id,std::string amount,std::string details,std::string extras="",int time=1000,int confirms=2){auto raw=Json("{\"txid\":"+rpc::Quote(std::string(64,id))+",\"amount\":"+amount+",\"time\":"+std::to_string(time)+",\"confirmations\":"+std::to_string(confirms)+",\"details\":"+details+extras+"}");auto tx=NormalizeHistoryTransaction(raw,std::string(64,id));Check(bool(tx),"valid canonical transaction");return *tx;}
HistoryTransaction Deposit(){return Tx('2',"10.00000000","[{\"category\":\"receive\",\"vout\":0,\"amount\":10.00000000}]");}
HistoryTransaction Multi(bool metadata=false){return Tx('1',"-3.00000000","[{\"category\":\"send\",\"vout\":0,\"amount\":-1.00000000,\"fee\":-0.00001000},{\"category\":\"send\",\"vout\":1,\"amount\":-2.00000000,\"fee\":-0.00001000}]",std::string(",\"fee\":-0.00001000")+(metadata?",\"replaced_by_txid\":"+rpc::Quote(H('7').hex()):""),2000);}
HistoryBatch Batch(){HistoryBatch b{Context(),"wallet",H('b').hex()};b.transactions={Deposit(),Multi()};b.balances.trusted=Money::Satoshis(699999000);b.coins={{{H('1'),2},Money::Satoshis(699999000),2,true,true,false}};b.full_query=b.stable=b.inventory_available=true;b.height=2;return b;}
void Models(){
    auto b=Batch();const auto& tx=b.transactions[1];Check(tx.wallet_delta.sats()==-300001000 && tx.details.size()==2,"multi-output fee counted exactly once");Check(tx.fee->lexeme=="-0.00001000" && tx.reported_amount.lexeme=="-3.00000000","raw numeric lexemes retained");
    auto self=Tx('3',"0.00000000","[{\"category\":\"send\",\"vout\":0,\"amount\":-2.00000000,\"fee\":-0.00001000},{\"category\":\"receive\",\"vout\":0,\"amount\":2.00000000}]",",\"fee\":-0.00001000");Check(self.wallet_delta.sats()==-1000,"self-transfer is fee only");
    auto precise=Tx('4',"1e-8","[{\"category\":\"receive\",\"vout\":0,\"amount\":\"0.00000001\"}]");Check(precise.reported_amount.value.sats()==1 && precise.reported_amount.lexeme=="1e-8" && precise.details[0].amount.quoted,"number exponent and quoted decimal stay exact");
    auto large=Tx('4',"90071992.54740993","[{\"category\":\"receive\",\"vout\":0,\"amount\":90071992.54740993}]");Check(large.wallet_delta.sats()==9007199254740993LL,"int64 amount above binary-float integer range");
    const auto witness=Tx('8',"2","[{\"category\":\"receive\",\"amount\":2,\"vout\":0}]",",\"wtxid\":"+rpc::Quote(H('9').hex()));
    Check(witness.wire_witness==H('9') && witness.previous_hex.empty(),"witness observation remains available without cached raw wire");
    const auto duplicate=Json("{\"txid\":"+rpc::Quote(H('1').hex())+",\"amount\":2,\"time\":1000,\"confirmations\":1,\"details\":[{\"category\":\"receive\",\"amount\":1,\"vout\":0},{\"category\":\"receive\",\"amount\":1,\"vout\":0}]}");Check(!NormalizeHistoryTransaction(duplicate,H('1').hex()),"duplicate output/category cannot double account");
    HistoryLedger ledger(Context(),"wallet");Check(ledger.SetPolicy({true,{},{}}) && !ledger.Totals().total && !ledger.Totals().has_rpc,"policy before observation cannot fabricate zero balances");Check(ledger.SetPolicy({false,{},{}}),"clear policy evidence");Check(ledger.Apply(b,1,1700000000000LL) && ledger.Complete(),"full known wallet reconciles exactly");Check(ledger.Rows().at(H('2').hex()).running_balance->sats()==1000000000 && ledger.Rows().at(H('1').hex()).running_balance->sats()==699999000,"chronological balances attach to txid rather than lexical/display order");Check(ledger.Totals().confirmed->sats()==699999000 && ledger.Totals().mempool->sats()==0 && ledger.Totals().rpc_fundable->sats()==699999000 && !ledger.Totals().spendable,"RPC fundability is distinct from unknown local policy");
    Check(ledger.SetPolicy({true,{},{}}) && ledger.Totals().spendable->sats()==699999000,"explicit empty policy gives exact spendable");Check(ledger.SetPolicy({true,{{H('1'),2}},{}}) && ledger.Totals().spendable->sats()==0 && ledger.Totals().frozen->sats()==699999000,"local freeze excludes without changing confirmation accounting");Check(ledger.SetPolicy({true,{},{{H('1'),2}}}) && ledger.Totals().spendable->sats()==0 && ledger.Totals().reserved->sats()==699999000,"reservation excludes exactly without duplicating frozen amounts");Check(!ledger.SetPolicy({true,{{H('1'),2}},{{H('1'),2}}}),"overlapping freeze/reservation cannot double classify");
    Check(ledger.Apply(b,2,1700000001000LL) && ledger.Rows().size()==2 && ledger.Totals().total->sats()==699999000,"repeated snapshot replaces stable transaction parents");Check(!ledger.Apply(b,2,1700000002000LL),"old sequence rejected");auto wrong=b;wrong.context.lock_epoch.value++;Check(!ledger.Apply(wrong,3,1700000002000LL),"old lock epoch rejected");wrong=b;wrong.daemon_wallet="other-wallet";Check(!ledger.Apply(wrong,3,1700000002000LL),"daemon wallet scope cannot contaminate");wrong=b;wrong.context.revision.value++;Check(!ledger.Apply(wrong,3,1700000002000LL),"revision fence retained");
    HistoryLedger partial(Context(),"wallet");b.full_query=false;Check(partial.Apply(b,1,1700000000000LL) && !partial.Complete() && !partial.Rows().begin()->second.running_balance,"matching suffix never fabricates an opening zero");b.full_query=true;b.limited=true;Check(partial.Apply(b,2,1700000001000LL) && partial.Limited() && !partial.Complete(),"scan limits are explicit and opening balance Unknown");b.limited=false;b.scanning=true;Check(partial.Apply(b,3,1700000002000LL) && partial.Scanning() && !partial.Complete(),"active rescan prevents completeness");b.scanning=false;b.pruned=true;Check(partial.Apply(b,4,1700000003000LL) && !partial.Complete(),"pruned coverage is not invented");b.pruned=false;b.balances.nonmempool=Money::Satoshis(-1000000000);Check(partial.Apply(b,5,1700000003500LL) && !partial.Complete() && partial.Totals().rpc.nonmempool.sats()==-1000000000 && !partial.Rows().begin()->second.running_balance,"signed nonmempool adjustment retained without inventing a running balance");b.balances.nonmempool=Money::Satoshis(0);b.stable=false;Check(partial.Apply(b,6,1700000004000LL) && !partial.Complete() && !partial.Totals().rpc_fundable,"mixed chain/balance observations stay incomplete and fundability Unknown");b.stable=true;b.balances.trusted=Money::Satoshis(700000000);Check(partial.Apply(b,7,1700000005000LL) && !partial.Complete() && !partial.Totals().confirmed,"RPC disagreement retains rows but no invented categories/running balance");
    b=Batch();auto immature=Tx('5',"0.00000000","[{\"category\":\"immature\",\"vout\":0,\"amount\":50.00000000}]",",\"generated\":true",3000,1);Check(immature.wallet_delta.sats()==5000000000 && immature.reported_amount.value.sats()==0,"immature reward does not inherit zero canonical credit");b.transactions.push_back(immature);b.balances.immature=Money::Satoshis(5000000000);b.coins.push_back({{H('5'),0},Money::Satoshis(5000000000),1,true,true,false});Check(ledger.Apply(b,3,1700000006000LL) && ledger.Complete() && ledger.Totals().rpc_fundable->sats()==699999000,"immature total distinct from confirmed/fundable");
    auto orphan=Tx('5',"0.00000000","[{\"category\":\"orphan\",\"vout\":0,\"amount\":50.00000000}]",",\"generated\":true",3000,0);orphan.removed_event=true;b.transactions={orphan};b.full_query=false;b.balances.immature=Money::Satoshis(0);b.coins.pop_back();Check(ledger.Apply(b,4,1700000007000LL) && ledger.Rows().size()==3 && ledger.Complete() && ledger.Rows().at(H('5').hex()).removed_event,"removed orphan retained without credit");
    b.transactions={immature};b.balances.immature=Money::Satoshis(5000000000);b.coins.push_back({{H('5'),0},Money::Satoshis(5000000000),1,true,true,false});Check(ledger.Apply(b,5,1700000008000LL) && ledger.Rows().at(H('5').hex()).removed_event && ledger.Complete(),"re-added transaction replaces same parent while removal event remains");
    auto confirmed_replacement=Multi(true);Check(confirmed_replacement.state==HistoryState::Confirmed,"current confirmation wins over historical replacement metadata");auto replaced=self;replaced.replaced_by=H('6');replaced.state=HistoryState::Replaced;b.transactions={replaced};Check(ledger.Apply(b,6,1700000009000LL) && ledger.Complete(),"replaced row never counts a second fee");auto conflict=self;conflict.txid=H('7');conflict.state=HistoryState::Conflicted;conflict.confirmations=-1;b.transactions={conflict};Check(ledger.Apply(b,7,1700000010000LL) && ledger.Complete(),"conflicted row contributes no balance");
    const auto date=ledger.Observed();const auto count=ledger.Rows().size();auto bad_height=b;bad_height.height=INT64_MAX;Check(!ledger.Apply(bad_height,8,1700000011000LL) && ledger.Observed()==date,"impossible backend height cannot overflow confirmation arithmetic");b.balances.trusted=Money::Satoshis(INT64_MAX);b.balances.immature=Money::Satoshis(1);Check(!ledger.Apply(b,8,1700000011000LL) && ledger.Observed()==date && ledger.Rows().size()==count,"overflow rejects atomically with old dated rows retained");
}
void Service(){
    auto context=Context();ServerCandidate profile;profile.wallet="wallet";profile.expected_genesis=context.network.genesis.hex();BackendCapabilities caps;caps.authenticated=caps.identity_verified=true;caps.wallet=WalletAvailability::Available;caps.candidate=profile;caps.genesis=profile.expected_genesis;for(const char* name:{"getwalletinfo","getbalances","listsinceblock","gettransaction"})caps.methods[name]={true,true,true,false,{"include_removed","blockhash","txid"}};
    RefreshIdentity identity{context,profile,1};int calls{};bool fail{};RefreshService service([&](const RefreshRequest& r,std::stop_token){++calls;RefreshReply reply{r.identity,r.generation,r.sequence};reply.observed_unix_ms=1700000000000LL+calls;if(fail)reply.errors[2]=rpc::Error::Connection;else {auto b=Batch();reply.history=HistoryDelta{Json("[]"),Json("[]"),H('b').hex(),std::move(b)};}return reply;});
    const auto settle=[&]{const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(2);while(service.Busy() && std::chrono::steady_clock::now()<end){service.Tick(0);std::this_thread::yield();}Check(!service.Busy(),"history worker settled");};
    Check(service.Bind(identity,caps,false,0),"normalized history binds full profile");service.Tick(0);settle();Check(service.View().ledger && service.View().ledger->Complete() && !service.View().history,"transactional consumer advances raw cursor only after adoption");const auto date=service.View().ledger->Observed();fail=true;Check(service.RequestNow(0),"manual history refresh admitted");service.Tick(0);settle();Check(service.View().ledger->Observed()==date && service.View().ledger->Rows().size()==2 && service.View().freshness[2]==Freshness::Stale,"refresh failure retains dated history");service.SetOffline(true,0);const auto before=calls;service.Tick(999999);Check(calls==before && service.View().freshness[2]==Freshness::Offline,"offline makes no transport work and dates cached rows");Check(service.SetHistoryPolicy(identity,{true,{},{}}),"local policy can apply to cached history without RPC");service.PrivacyLock();service.Tick(999999);Check(!service.View().ledger && service.View().locked && !service.SetHistoryPolicy(identity,{true,{},{}}),"privacy lock removes history and blocks policy adoption");

    std::mutex mutex;std::condition_variable changed;bool entered{},release{};
    RefreshService held([&](const RefreshRequest& request,std::stop_token){std::unique_lock lock(mutex);entered=true;changed.notify_all();changed.wait_for(lock,std::chrono::seconds(2),[&]{return release;});RefreshReply reply{request.identity,request.generation,request.sequence};reply.observed_unix_ms=1700000001000LL;auto batch=Batch();batch.context=request.identity.context;reply.history=HistoryDelta{Json("[]"),Json("[]"),H('b').hex(),std::move(batch)};return reply;});
    Check(held.Bind(identity,caps,false,0),"held normalized history bound");held.Tick(0);{std::unique_lock lock(mutex);Check(changed.wait_for(lock,std::chrono::seconds(1),[&]{return entered;}),"normalized request held at actual worker boundary");}held.PrivacyLock();auto next=identity;next.context.lock_epoch.value++;Check(held.Bind(next,caps,false,0),"fresh lock epoch can bind independently");held.SetOffline(true,0);{std::lock_guard lock(mutex);release=true;}changed.notify_all();const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(2);while(held.Busy() && std::chrono::steady_clock::now()<end){held.Tick(0);std::this_thread::yield();}Check(!held.Busy() && held.View().ledger && held.View().ledger->Rows().empty() && !held.View().ledger->Totals().has_rpc,"late normalized reply cannot disclose or mutate the new epoch; worker settled");
}
}
int main(){try{Models();Service();std::cout<<"{\"passed\":true,\"checks\":"<<checks<<"}\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
